// Connection Service: manages the professional graph with degree-of-connection rules
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<GraphDbContext>(opt =>
    opt.UseSqlServer(builder.Configuration.GetConnectionString("GraphDb"))
);
builder.Services.AddStackExchangeRedisCache(opt =>
    opt.Configuration = builder.Configuration.GetConnectionString("Redis")
);

var app = builder.Build();

app.MapPost("/connections/request", async (ConnectionRequest req, GraphDbContext db) =>
{
    // Prevent duplicate requests and self-connections
    var exists = await db.Connections.AnyAsync(c =>
        (c.SourceUserId == req.FromUserId && c.TargetUserId == req.ToUserId) ||
        (c.SourceUserId == req.ToUserId && c.TargetUserId == req.FromUserId)
    );
    if (exists) return Results.Conflict("Connection already exists or pending");

    var connection = new Connection
    {
        Id = Guid.NewGuid(),
        SourceUserId = req.FromUserId,
        TargetUserId = req.ToUserId,
        Status = ConnectionStatus.Pending
    };
    db.Connections.Add(connection);
    await db.SaveChangesAsync();

    // Invalidate cached degree-of-connection for both users
    await cache.RemoveAsync($"degree:{req.FromUserId}:{req.ToUserId}");
    await cache.RemoveAsync($"degree:{req.ToUserId}:{req.FromUserId}");

    // Trigger notification to recipient
    await bus.Publish(new ConnectionRequestedEvent(connection.Id, req.FromUserId, req.ToUserId));
    return Results.Created($"/connections/{connection.Id}", connection);
})
.WithName("SendConnectionRequest");

app.MapGet("/connections/degree", async (string userIdA, string userIdB, GraphDbContext db, IRedisCache cache) =>
{
    var cacheKey = $"degree:{userIdA}:{userIdB}";
    var cached = await cache.GetStringAsync(cacheKey);
    if (cached != null) return Results.Ok(new { degree = int.Parse(cached) });

    // BFS to find shortest path between users in the professional graph
    var degree = await BfsShortestPathAsync(db, userIdA, userIdB);
    await cache.SetStringAsync(cacheKey, degree.ToString(),
        new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1) }
    );
    return Results.Ok(new { degree });
})
.WithName("GetConnectionDegree");

app.MapGet("/health", () => Results.Ok());
app.Run();

// BFS traversal limited to 3 degrees (LinkedIn's visible network limit)
async Task<int> BfsShortestPathAsync(GraphDbContext db, string start, string end)
{
    var visited = new HashSet<string> { start };
    var queue = new Queue<(string userId, int degree)>();
    queue.Enqueue((start, 0));

    while (queue.Count > 0)
    {
        var (current, degree) = queue.Dequeue();
        if (current == end) return degree;
        if (degree >= 3) continue;

        var neighbors = await db.Connections
            .Where(c => c.SourceUserId == current && c.Status == ConnectionStatus.Accepted)
            .Select(c => c.TargetUserId)
            .ToListAsync();

        foreach (var neighbor in neighbors)
        {
            if (visited.Add(neighbor))
                queue.Enqueue((neighbor, degree + 1));
        }
    }
    return -1; // Not connected within 3 degrees
}
